text(await tools.exec_command({cmd:"$ErrorActionPreference = 'Stop'
$guardedDrawingPaths = @('cad/out/sldprt/measuring-stick.SLDPRT','cad/out/sldprt/.measuring-stick.execution','cad/out/slddrw/measuring-stick.SLDDRW','cad/out/pdf/measuring-stick.pdf','cad/out/png/measuring-stick_drawing.png')
$guardedDrawingPaths | ForEach-Object {
    $guardedPath = (Resolve-Path -LiteralPath $_).Path
    $guardedStream = [System.IO.File]::Open($guardedPath,[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
    try { $guardedHash = [Convert]::ToHexString([System.Security.Cryptography.SHA256]::HashData($guardedStream)) } finally { $guardedStream.Dispose() }
    [PSCustomObject]@{Path=$guardedPath;SHA256=$guardedHash}
} | ConvertTo-Json
git status --short --branch
Get-Process -Id 45848 | Select-Object Id,Responding,@{Name='PrivateGiB';Expression={[math]::Round($_.PrivateMemorySize64/1GB,2)}} | ConvertTo-Json","workdir":"C:/src/ha-foundations-integration","max_output_tokens":2300}));

text(await tools.exec_command({cmd:"$ErrorActionPreference = 'Stop'
$measuringDrawingPaths = @('cad/out/sldprt/measuring-stick.SLDPRT','cad/out/sldprt/.measuring-stick.execution','cad/out/slddrw/measuring-stick.SLDDRW','cad/out/pdf/measuring-stick.pdf','cad/out/png/measuring-stick_drawing.png')
