    try { $measuringHash = [Convert]::ToHexString([System.Security.Cryptography.SHA256]::HashData($measuringStream)) } finally { $measuringStream.Dispose() }
    [PSCustomObject]@{Path=$measuringPath;SHA256=$measuringHash}
} | ConvertTo-Json
$measuringTraceBefore = (Get-Item -LiteralPath cad/out/reports/telemetry/traces.jsonl).Length
$measuringLogBefore = (Get-Item -LiteralPath cad/out/reports/telemetry/logs.jsonl).Length
$env:HARMONIC_SW_AUTOSTART = '1'
$env:HARMONIC_REMOTE_CACHE_MODE = 'off'
$env:HARMONIC_TELEMETRY_DIR = 'C:/src/ha-foundations-integration/cad/out/reports/telemetry'
